#!/usr/bin/env bash
# Checagem antes de ligar o coletor (runbook, 16:30). Sai com 1 se algo crítico falhar.
#   scripts/preflight.sh       1º turno
#   scripts/preflight.sh 2t    2º turno: banco data/apuracao-2t.sqlite, régua do 1º turno, -cs.json do
#                              pleito 3221 e leitura das views públicas da totalização paralela
set -u
cd "$(dirname "$0")/.." || exit 1
TURNO2=0
if [ "${1:-}" = "2t" ]; then
  TURNO2=1
  export APURACAO_ELEICOES="${APURACAO_ELEICOES:-6258,6260}"
  export APURACAO_PLEITO="${APURACAO_PLEITO:-3221}"
---
{
  "dwell": 20,
  "itens": [
    { "view": "pres", "dwell": 25 },
    { "view": "regioes", "dwell": 22 },
    { "view": "ufs", "dwell": 22 },
    { "view": "evolucao", "dwell": 24 },
    { "view": "gov-2t", "dwell": 24 },
    { "view": "abstencao", "dwell": 22 },
    { "view": "atraso", "dwell": 20 },
    { "view": "pausas", "dwell": 20 },
    { "view": "paralela", "dwell": 20 },
    { "view": "alertas", "dwell": 16 },
    { "view": "pres-uf", "uf": "$destaque", "max": 3, "dwell": 20 }
  ],
  "destaque": ["SP", "MG", "RJ", "BA", "RS", "PR", "PE", "CE", "PA", "SC", "GO", "MA"]
}
---
// Parâmetros extras do ensaio no hash (#mock=1&turno=2&t0=150&falha=paralela&sem1t=1), lidos
// só na carga da página. Sem DOM, para os testes.

import { ROTAS_2T } from "./doist.ts";
import type { Rota2T } from "./doist.ts";
import type { FalhaMock } from "./mock.ts";

export interface ParamsMock {
  turno: 1 | 2;
  /** Minutos após 17:00 em que o relógio simulado começa; null deixa o padrão (16:59:30). */
  inicioMin: number | null;
  falhas: Partial<Record<Rota2T, FalhaMock>>;
  sem1t: boolean;
  /** Relógio parado em `t0`: toda leitura devolve os mesmos números. */
  congelar: boolean;
}

const ROTA_VALIDA = new Set<string>(ROTAS_2T);
const FALHA_VALIDA = new Set<string>(["erro", "pendente", "fonte"]);

/**
 * `turno` (1 ou 2, padrão 2: o 1º turno já passou); `t0` em minutos; `falha=rota[:modo],rota...`
 * com modo `erro` (padrão), `pendente` ou `fonte`; `evolucao` vale para as duas rotas de evolução;
 * `sem1t=1` tira a régua do 1º turno; `congelar=1` para o relógio em `t0`.
 */
export function lerParamsMock(hash: string): ParamsMock {
  const p = new URLSearchParams(hash.replace(/^#/, ""));
  const turno = p.get("turno") === "1" ? 1 : 2;
  const t0 = p.get("t0");
  const inicioMin = t0 !== null && t0.trim() !== "" && Number.isFinite(Number(t0)) ? Number(t0) : null;
---
// Uso: bun run scripts/exportar-publico.ts [--saida ../docs/assets/apuracao_2t] [--base http://127.0.0.1:4180]
//
// Exporta o estado público da apuração do 2º turno (25/10/2026) para o GitHub Pages.
// Chama a API local do telão (porta em APURACAO_PORT, padrão 4180), grava um JSON compacto por
// rota em docs/assets/apuracao_2t/ e um manifest.json com gerado_em, turno, sha256 e bytes de
// cada arquivo e a lista de rotas pendentes (resposta {pendente:true}, erro ou prazo estourado).
//
// Rota com erro não derruba a exportação: o arquivo anterior fica como está e a rota entra em
// `pendentes`. Sem arquivo anterior, grava {"pendente":true}. Nunca grava identificador pessoal:
// campos com nome de CPF, e-mail, telefone ou título de eleitor são removidos antes de gravar.
// Código de saída: 0 se gravou o manifesto, 1 se nem o manifesto pôde ser gravado.

const RAIZ = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const PADRAO_SAIDA = join(RAIZ, "..", "docs", "assets", "apuracao_2t");
const PRAZO_MS = 20_000;
const ALVO_BYTES = 2 * 1024 * 1024;
const PROIBIDOS = /^(cpf|email|e_mail|telefone|celular|titulo|titulo_eleitor|nr_titulo|nome_eleitor|ip|ip_hash)$/i;

interface Rota {
  arquivo: string;
  caminho: string;
---
#!/usr/bin/env bash
# Publica a apuração do 2º turno no GitHub Pages: exporta os JSON públicos e faz commit + push.
#
# Ligar (em segundo plano, a partir da raiz do repositório PNAD ou de apuracao/):
#   nohup apuracao/scripts/publicar-loop.sh >/dev/null 2>&1 &
# Variáveis: INTERVALO_S (padrão 300), APURACAO_PORT (padrão 4180), PUSH=0 para só commitar.
# Desligar:
#   kill "$(cat apuracao/data/logs/publicar.pid)"      # ou: pkill -f publicar-loop.sh
# Log do dia: apuracao/data/logs/publicar-AAAAMMDD.log
# Só toca em docs/assets/apuracao_2t: o commit leva exclusivamente essa pasta. Falha de rede ou de
# push não interrompe o laço (loga e tenta de novo no próximo ciclo). Rótulo público: dados do
# telão, soma de arquivos do TSE, sem projeção.
set -u
AQUI="$(cd "$(dirname "$0")/.." && pwd)"
REPO="$(cd "$AQUI/.." && pwd)"
PASTA="docs/assets/apuracao_2t"
INTERVALO_S="${INTERVALO_S:-300}"
mkdir -p "$AQUI/data/logs"
PIDFILE="$AQUI/data/logs/publicar.pid"
LOG="$AQUI/data/logs/publicar-$(date +%Y%m%d).log"

